class Solution:
    def longestPalindrome(self, s: str) -> str:
        def extend(l,r):
            while l>=0 and r< len(s) and s[l] == s[r]:
                l-=1
                r+=1
            return s[l+1: r]
        ans = ""

        for i in range(len(s)):
            odd = extend(i,i)
            even = extend(i,i+1)

            if len(odd) > len(ans):
                ans = odd
            if len(even) > len(ans):
                ans = even

        return ans

