class Solution:
    def myAtoi(self, s: str) -> int:
        intmax, intmin = 2**31 - 1, -2**31
        i,n = 0, len(s)
        while i<n and s[i] == " ": 
            i+=1

        sign = 1
        if i<n and (s[i] == "+" or s[i] == "-"):
            if s[i] == "-":
                sign = -1

            i+=1

        ans = 0
        while i<n and s[i].isdigit():
            d = int(s[i])
            if (ans > intmax // 10) or (ans == intmax//10 and d > 7):
                return intmax if sign == 1 else intmin

            ans = ans*10 + d
            i+=1

        return ans * sign

