class Solution:
    def maxArea(self, height: List[int]) -> int:
        n = len(height)
        l, r = 0, n-1
        ans = 0

        while l < r:
            ans = max(min(height[l], height[r]) * (r-l), ans)
            if height[l] <height[r]:
                l+=1

            else:
                r-=1

        return ans

