class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        ans = nums[0]+nums[1]+nums[2]

        nums.sort()
        n = len(nums)

        for i in range(n-2):
            if i>0 and nums[i] == nums[i-1]:
                continue

            l = i+1
            r = n-1

            while l<r:
                s = nums[i] + nums[l] + nums[r]
                if target == s:
                    return s

                if abs(target - s) < abs(target- ans):
                    ans = s

                if s < target:
                    l += 1

                else:
                    r-=1

        return ans

