# Next Permutation
class Solution:
    def nextPermutation(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        def rev(l,r):
            while l<r:
                nums[l], nums[r] = nums[r], nums[l]
                l,r = l+1, r-1

        n = len(nums)
        dip = next((i for i in range(n-2,-1,-1) if nums[i+1] > nums[i]), -1)
        if dip >= 0:
            swap = next((j for j in range(n-1,-1,-1) if nums[j] > nums[dip]),-1)
            nums[dip], nums[swap] = nums[swap], nums[dip]

        rev(dip+1, n-1)

