class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char,int> tmap = {};
        for (char c: t){
            tmap[c]++;
        }

        int required = tmap.size();
        int formed = 0;
        unordered_map<char, int> window = {};

        int minlen = INT_MAX;
        int bestleft = 0;
        int l = 0;

        for (int r=0; r<s.size(); r++){
            char rightchar = s[r];
            window[rightchar]++;
            if (tmap.count(rightchar) and tmap[rightchar] == window[rightchar]){
                formed++;
            }

            while (l<=r and required == formed){
                int length = r-l+1;
                if (length < minlen){
                    minlen = length;
                    bestleft = l;
                }
                char leftchar = s[l];
                window[leftchar]--;
                if (tmap[leftchar] > window[leftchar]){
                    formed--;
                }

                l++;

            }
        }

        return (minlen == INT_MAX ? "" : s.substr(bestleft,minlen));



    }
};

