        n = len(nums)
        ans = []
        nums.sort()
        for mask in range(1<<n):
            subset = []
            for i in range(n):
                if (mask >> i) & 1:
                    if i>0 and ((mask >> (i-1)) & 1) == 0 and  nums[i]  == nums[i-1]:
                        break
                    subset.append(nums[i])
            else:
                ans.append(subset)

