class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        q, res = [root], []
        reverse = False

        while q:
            level = [node.val for node in q]
            res.append(level[::-1] if reverse else level)
            q = [child for node in q for child in (node.left, node.right) if child]
            reverse = not reverse

        return res

