class Solution:
    def numIslands2(self, m: int, n: int, positions: List[List[int]]) -> List[int]:
        class UnionFind:
            def __init__(self, size):
                self.parent = [-1] * size   # ← singular, consistent everywhere
                self.rank = [0] * size
                self.count = 0

            def findparent(self, x):
                if self.parent[x] != x:
                    self.parent[x] = self.findparent(self.parent[x])
                return self.parent[x]

            def union(self, x, y):
                px, py = self.findparent(x), self.findparent(y)
                if px == py:
                    return False
                if self.rank[px] > self.rank[py]:    # ← brackets not ()
                    self.parent[py] = px
                elif self.rank[px] < self.rank[py]:  # ← brackets not ()
                    self.parent[px] = py
                else:
                    self.parent[py] = px
                    self.rank[px] += 1
                self.count -= 1
                return True

        uf = UnionFind(m * n)
        dirs = ((1,0),(-1,0),(0,1),(0,-1))
        result = []

        for x, y in positions:
            index = x * n + y
            if uf.parent[index] != -1:       # duplicate position
                result.append(uf.count)
                continue                      # ← also need to skip re-adding

            uf.parent[index] = index
            uf.count += 1

            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:   # ← correct bounds
                    newindex = nx * n + ny
                    if uf.parent[newindex] != -1:
                        uf.union(index, newindex)

            result.append(uf.count)

        return result

