        self.count = 0
        prefix = {0: 1}

        def dfs(node, curr_sum):
            if not node:
                return

            curr_sum += node.val
            self.count += prefix.get(curr_sum - targetSum, 0)
            prefix[curr_sum] = prefix.get(curr_sum, 0) + 1

            dfs(node.left, curr_sum)
            dfs(node.right, curr_sum)

            prefix[curr_sum] -= 1

        dfs(root, 0)
