class Solution:
    def longestConsecutive(self, root: Optional[TreeNode]) -> int:

        def fn(node): 
            """Return longest increasing & decreasing sequence starting from node."""
            if not node: return 0, 0
            li, ld = fn(node.left)
            ri, rd = fn(node.right)
            inc = dec = 1
            if node.left: 
                if node.left.val + 1 == node.val: inc = 1 + li 
                elif node.left.val - 1 == node.val: dec = 1 + ld
            if node.right: 
                if node.right.val + 1 == node.val: inc = max(inc, 1 + ri)
                elif node.right.val - 1 == node.val: dec = max(dec, 1 + rd)
            self.ans = max(self.ans, inc + dec - 1)
            return inc, dec

        self.ans = 0 
        fn(root)
        return self.ans

