        def same(p,q):
            if not p or not q:
                return p == q

            if p.val != q.val:
                return False

            return same(p.left, q.left) and same(p.right, q.right)

        def subtree(root, subRoot):
            if not root:
                return False

            if same(root,subRoot):
                return True

            return subtree(root.left, subRoot) or subtree(root.right, subRoot)

