class Solution:
    def widthOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        q = deque([(root, 0)])
        max_width = 1

        while q:
            level_len = len(q)
            left = q[0][1]
            right = q[-1][1]
            max_width = max(max_width, right - left + 1)

            for _ in range(level_len):
                node, idx = q.popleft()
                if node.left:
                    q.append((node.left, idx*2 + 1))
                if node.right:
                    q.append((node.right, idx*2 + 2))

        return max_width

