class Solution:
    def candyCrush(self, board: List[List[int]]) -> List[List[int]]:
        m, n = len(board), len(board[0])

        while True:
            crushable = set()

            # Horizontal and vertical in one loop
            for i in range(m):
                for j in range(n):
                    if i < m - 2 and board[i][j] == board[i+1][j] == board[i+2][j] != 0:
                        crushable.update([(i,j), (i+1,j), (i+2,j)])
                    if j < n - 2 and board[i][j] == board[i][j+1] == board[i][j+2] != 0:
                        crushable.update([(i,j), (i,j+1), (i,j+2)])

            if not crushable:
                return board

            # Crush and apply gravity in one pass
            for j in range(n):
                col = [board[i][j] for i in range(m) if (i,j) not in crushable]
                col = [0] * (m - len(col)) + col  # Zeros on top
                for i in range(m):
                    board[i][j] = col[i]

