class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:
        graph = defaultdict(list)
        for u,v ,t in times:
            graph[u].append((v,t))

        pq = [(0,k)]
        distances = {k:0}

        while pq:
            currTime, currNode = heappop(pq)
            for nextNode, timeToNext in graph[currNode]:
                newTime = currTime+ timeToNext
                if newTime < distances.get(nextNode, float('inf')):
                    distances[nextNode] = newTime
                    heappush(pq, (newTime, nextNode))

        if n ==len(distances): return max(distances.values())

        return -1

