class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start_node: int, end_node: int) -> float:
        graph = defaultdict(list)
        for (u,v),p in zip(edges, succProb):
            w = -math.log(p) if p>0 else float('inf')
            graph[u].append((v,w))
            graph[v].append((u,w))

        pq = [(0.0,start_node)]
        distances = {start_node: 0.0}

        while pq:
            cWeight, cNode = heappop(pq)


            if cNode == end_node:
                return math.exp(-cWeight)

            if cWeight > distances.get(cNode, float('inf')):
                continue 

            for (nextNode, weightToNext) in graph[cNode]:
                totalWeight = cWeight + weightToNext
                if totalWeight < distances.get(nextNode, float('inf')):
                    distances[nextNode] = totalWeight
                    heappush(pq, (totalWeight, nextNode))

        return 0.0

