import heapq
from typing import List, Tuple, Dict

class Solution:
    def minimumEffortPath(self, heights: List[List[int]]) -> int:
        m, n = len(heights), len(heights[0])
        directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]

        pq = [(0, 0, 0)]  
        efforts = {(0, 0): 0} 

        while pq:
            effort, x, y = heapq.heappop(pq)
            if effort > efforts.get((x, y), float('inf')):
                continue

            if x == m - 1 and y == n - 1:
                return effort

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    next_effort = max(effort, abs(heights[nx][ny] - heights[x][y]))
                    if next_effort < efforts.get((nx, ny), float('inf')):
                        efforts[(nx, ny)] = next_effort
                        heapq.heappush(pq, (next_effort, nx, ny))

        return 0

