class Solution:
    def countFairPairs(self, nums: List[int], lower: int, upper: int) -> int:
        def low(start, target):
            l = start
            r = len(nums)-1

            while l<=r:
                m = (l+r)//2
                if nums[m]>= target:
                    r = m-1

                else:
                    l = m+1

            return l


        def up(start, target):
            l = start
            r = len(nums)-1

            while l<=r:
                m = (l+r)//2
                if nums[m]> target:
                    r = m-1

                else:
                    l = m+1

            return l



        nums.sort()
        ans = 0
        for i in range(len(nums)):
            l = low(i+1, lower-nums[i])
            u = up(i+1, upper-nums[i])

            ans += u-l

        return ans

