from collections import defaultdict, deque

class Solution:
    def findMinHeightTrees(self, N: int, edges: List[List[int]]) -> List[int]:
        #using 0 to n-1 for this question 
        #if only 1 value 0 just wrap and return it as list
        if N == 1: 
            return [0]

        # use set in defaultdict instead of list
        #.. for easy removal of leaf nodes later by .remove
        graph = defaultdict(set)
        for u, v in edges:
            graph[u].add(v)
            graph[v].add(u)

        q_of_leaves = deque()
        for node in range(N):
            if len(graph[node]) == 1:
                q_of_leaves.append(node)

        while N > 2:
            qLen = len(q_of_leaves)
            N -= qLen
            for _ in range(qLen):
                leafnode = q_of_leaves.popleft()
                for neighbor in graph[leafnode]:
                    graph[neighbor].remove(leafnode) # removing leaf nodes as you go
                    if len(graph[neighbor]) == 1:
                        q_of_leaves.append(neighbor)


        return list(q_of_leaves)

