from collections import deque
from typing import List

class Solution:
    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> List[str]:
        def get_hostname(url: str) -> str:
            # Extract hostname from URL
            # Example: "http://news.yahoo.com/news" → "news.yahoo.com"
            return url.split('/')[2]

        target_host = get_hostname(startUrl)
        visited = {startUrl}
        queue = deque([startUrl])

        while queue:
            url = queue.popleft()

            for link in htmlParser.getUrls(url):
                if link not in visited and get_hostname(link) == target_host:
                    visited.add(link)
                    queue.append(link)

        return list(visited)
